"""The ``pennywise`` command."""

import argparse
import csv
import io
import json
import os
import sys
from typing import List, Optional

from .ledger import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_amount,
    parse_category,
    parse_date,
    parse_note,
)

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class UsageError(Exception):
    """The file cannot be read/written or the command line is wrong (exit 2)."""


class LedgerError(Exception):
    """The ledger or the entry given to ``add`` has a mistake (exit 1)."""


def _date_arg(text: str):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc))


def _decode(data: bytes, name: str) -> str:
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise UsageError("{}: not valid UTF-8 text ({})".format(name, exc))


def _read_text(path: str) -> str:
    if path == "-":
        return _decode(sys.stdin.buffer.read(), "<stdin>")
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError as exc:
        raise UsageError("{}: {}".format(path, exc.strerror or exc))
    return _decode(data, path)


def _load(path: str) -> List[Entry]:
    text = _read_text(path)
    try:
        return parse(text)
    except ParseError as exc:
        name = "<stdin>" if path == "-" else path
        raise LedgerError("{}: {}".format(name, exc))


def _sorted(entries: List[Entry]) -> List[Entry]:
    # sorted() is stable, so same-day entries keep file order.
    return sorted(entries, key=lambda e: e.date)


def _entry_dict(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def cmd_balance(args) -> str:
    total = balance(_load(args.file))
    if args.json:
        return json.dumps({"balance": format_amount(total)}) + "\n"
    return format_amount(total) + "\n"


def cmd_summary(args) -> str:
    entries = _load(args.file)
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    names = sorted(groups)
    if args.json:
        return json.dumps({n: format_amount(groups[n]) for n in names}) + "\n"
    return "".join("{}  {}\n".format(n, format_amount(groups[n])) for n in names)


def cmd_list(args) -> str:
    entries = filter_entries(
        _load(args.file), category=args.category, since=args.since, until=args.until
    )
    entries = _sorted(entries)
    if args.json:
        return json.dumps([_entry_dict(e) for e in entries]) + "\n"
    return "".join(format_entry(e) + "\n" for e in entries)


def cmd_export(args) -> str:
    entries = _sorted(_load(args.file))
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return buf.getvalue()


def cmd_add(args) -> str:
    path = args.file
    if path == "-":
        raise UsageError("add needs a file name, not '-'")

    existing = b""
    try:
        with open(path, "rb") as f:
            existing = f.read()
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise UsageError("{}: {}".format(path, exc.strerror or exc))

    # Line number the new entry will occupy, for error messages.
    line_no = existing.count(b"\n") + 1
    if existing and not existing.endswith(b"\n"):
        line_no += 1
    try:
        entry = Entry(
            date=parse_date(args.date),
            category=parse_category(args.category),
            amount=parse_amount(args.amount),
            note=parse_note(args.note or ""),
        )
    except ValueError as exc:
        raise LedgerError("invalid entry (line {}): {}".format(line_no, exc))

    line = format_entry(entry)
    data = line + "\n"
    if existing and not existing.endswith(b"\n"):
        data = "\n" + data
    try:
        with open(path, "ab") as f:
            f.write(data.encode("utf-8"))
    except OSError as exc:
        raise UsageError("{}: {}".format(path, exc.strerror or exc))
    return line + "\n"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell you where the money went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True
    file_help = "ledger file ('-' for standard input)"

    p = sub.add_parser("balance", help="print the total of all amounts")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=cmd_balance)

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=cmd_summary)

    p = sub.add_parser("list", help="print matching entries, oldest first")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=cmd_list)

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")
    p.set_defaults(func=cmd_add)

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--format", choices=["csv"], default="csv")
    p.set_defaults(func=cmd_export)

    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE
    try:
        output = args.func(args)
    except LedgerError as exc:
        print("pennywise: {}".format(exc), file=sys.stderr)
        return EXIT_LEDGER
    except UsageError as exc:
        print("pennywise: {}".format(exc), file=sys.stderr)
        return EXIT_USAGE
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        # Output piped into e.g. `head`; silence the error on interpreter exit.
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
